using System.Collections.Generic;
using UnityEngine;

/// <summary>
/// Material library. Every material is an asset under Resources/Materials
/// (generated by the editor's GraphicsSetup), so shaders and their variants are
/// part of player builds; this class just loads, caches, tints and re-tiles them.
/// </summary>
public static class Mats
{
    static readonly Dictionary<string, Material> cache = new Dictionary<string, Material>();
    static Material fallback;

    /// <summary>Shared material asset by name.</summary>
    public static Material Get(string name)
    {
        if (cache.TryGetValue(name, out var m) && m != null) return m;
        m = Resources.Load<Material>("Materials/" + name);
        if (m == null)
        {
            Debug.LogWarning($"Material '{name}' is missing – run Tools ▸ Prdivý závod ▸ Rebuild graphics settings and materials.");
            m = Fallback();
        }
        cache[name] = m;
        return m;
    }

    /// <summary>New instance of a library material with a different base colour.</summary>
    public static Material Tinted(string name, Color color, float tiling = 1f)
    {
        var m = new Material(Get(name)) { color = color };
        if (!Mathf.Approximately(tiling, 1f)) m.mainTextureScale = new Vector2(tiling, tiling);
        return m;
    }

    /// <summary>Cached variant of a library material whose textures repeat <paramref name="tiling"/> times per UV unit.</summary>
    public static Material Tiled(string name, float tiling)
    {
        string key = name + "@" + tiling.ToString("0.###");
        if (cache.TryGetValue(key, out var m) && m != null) return m;
        m = new Material(Get(name)) { mainTextureScale = new Vector2(tiling, tiling) };
        cache[key] = m;
        return m;
    }

    static Material Fallback()
    {
        if (fallback != null) return fallback;
        var shader = Shader.Find("Universal Render Pipeline/Lit");
        if (shader == null) shader = Shader.Find("Standard");
        fallback = new Material(shader) { color = new Color(0.6f, 0.6f, 0.6f) };
        return fallback;
    }
}
